input.command:
cd "$TMPDIR/memory-ladder-runs/global-activation" && python3 - <<'EOF'
import json, glob, re
CONTENT = ('"recovered"', ".rubric.json", "_comment", "## Run 1", "## Run 2", "Recovered the recorded")
HARN = ("memory-ladder", "memory_ladder", "rubric")
for sp in sorted(glob.glob("c*-r*/stream.jsonl")):
    run = sp.split("/")[0]
    content_hits, harn_hits = [], []
    for line in open(sp):
        try: ev = json.loads(line)
        except Exception: continue
        if ev.get("type") != "user": continue
        for b in ev.get("message", {}).get("content", []):
            if isinstance(b, dict) and b.get("type") == "tool_result":
                body = b.get("content"); body = body if isinstance(body, str) else json.dumps(body)
                for m in CONTENT:
                    if m in body: content_hits.append(m)
                for m in HARN:
                    if m in body.lower():
                        i = body.lower().find(m)
                        harn_hits.append(body[max(0,i-60):i+80].replace("\n"," "))
    print(run, "| content-marker hits:", len(content_hits), set(content_hits) if content_hits else "")
    if harn_hits:
        print("   first harness-word context:", harn_hits[0][:150])
EOF

