--- a/internal/cli/command/facts/deps.go
+++ b/internal/cli/command/facts/deps.go
@@ -12,6 +12,8 @@ import (

 	"github.com/entireio/entire-brain/factmerge"
 	"github.com/entireio/entire-brain/internal/cli/internal/base"
+	"github.com/entireio/entire-brain/internal/cli/internal/factstore"
+	bmanifest "github.com/entireio/entire-brain/internal/cli/internal/manifest"
 	"github.com/spf13/cobra"
 )

@@ -43,8 +45,9 @@ type Deps struct {
 	// served, resolving the receipt clock and worktree HEAD from opts.
 	RecordServedFacts func(errW io.Writer, ctx context.Context, opts base.Options, brainDir, branch, surface, repoDir, taskText string, served []factmerge.Record)
 	// EmptyResultBlindSpot explains an empty result on a branch whose store
-	// holds memories elsewhere.
-	EmptyResultBlindSpot func(brainDir, branch string) string
+	// holds memories elsewhere. The caller hands over the manifest and store
+	// integrity it already computed, so the explainer re-reads neither.
+	EmptyResultBlindSpot func(brainDir, branch string, manifest *bmanifest.Manifest, integrity factstore.Integrity) string
 	// RunRecallEvidence runs recall's deterministic evidence mode, which still
 	// lives with the cli-resident evidence engine.
 	RunRecallEvidence func(cmd *cobra.Command, brainDir, branch, query string, limit, budget int, jsonOut bool) error
diff --git a/internal/cli/command/facts/facts_read_cmd.go b/internal/cli/command/facts/facts_read_cmd.go
index 0aac6ddb1..b8516dc6a 100644
--- a/internal/cli/command/facts/facts_read_cmd.go
+++ b/internal/cli/command/facts/facts_read_cmd.go
@@ -100,10 +100,26 @@ func NewRecall(cfg Config) *cobra.Command {
 			if evidence {
 				return cfg.Deps.RunRecallEvidence(cmd, brainDir, resolvedBranch, query, limit, evidenceBytes, jsonOut)
 			}
-			allFacts, err := factstore.Load(brainDir)
+			// One read serves the records, the integrity cross-check, and (on
+			// an empty result) the blind-spot explainer; re-reading for each
+			// was recall's dominant avoidable cost (COR-2313).
+			var storeWarning string
+			manifest, manifestErr := bmanifest.Load(brainDir)
+			var factsSource *bmanifest.FactSource
+			if manifestErr != nil {
+				storeWarning = "memory source manifest unavailable: " + manifestErr.Error()
+			} else if manifest != nil && manifest.Sources != nil {
+				factsSource = manifest.Sources.Facts
+			}
+			allFacts, integrity, err := factstore.LoadWithIntegrity(brainDir, factsSource)
 			if err != nil {
 				return err
 			}
+			if storeWarning == "" && !integrity.OK() {
+				// A short or collided store must never read as a smaller but
+				// healthy corpus.
+				storeWarning = integrity.Warning()
+			}
 			// The store is flat; an explicit --branch narrows to records
 			// stamped with that branch, and nothing is implied from the
 			// checked-out branch.
@@ -133,14 +149,6 @@ func NewRecall(cfg Config) *cobra.Command {
 					allFacts, globalIDs = retrieval.MergeGlobalFacts(allFacts, globalFacts)
 				}
 			}
-			var storeWarning string
-			if _, manifestErr := bmanifest.Load(brainDir); manifestErr != nil {
-				storeWarning = "memory source manifest unavailable: " + manifestErr.Error()
-			} else if integrity := factstore.InspectBrain(brainDir); !integrity.OK() {
-				// A short or collided store must never read as a smaller but
-				// healthy corpus.
-				storeWarning = integrity.Warning()
-			}
 			candidateFacts := allFacts
 			var eligibility *FactEligibilityAudit
 			if eligibleBefore != "" || sessionDatesPath != "" || len(excludeSessionIDs) > 0 {
@@ -218,7 +226,7 @@ func NewRecall(cfg Config) *cobra.Command {
 					out["warnings"] = append(warnings, storeWarning)
 				}
 				if len(matches) == 0 {
-					if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch); note != "" && storeWarning == "" {
+					if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch, manifest, integrity); note != "" && storeWarning == "" {
 						out["blind_spot"] = note
 					}
 				}
@@ -240,7 +248,7 @@ func NewRecall(cfg Config) *cobra.Command {
 					if storeWarning != "" {
 						fmt.Fprintln(out, "warning: "+storeWarning)
 					}
-					if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch); note != "" && storeWarning == "" {
+					if note := cfg.Deps.EmptyResultBlindSpot(brainDir, resolvedBranch, manifest, integrity); note != "" && storeWarning == "" {
